import AppKit
import MyPasteCore
import CryptoKit

/// Polls NSPasteboard.general (macOS has no change notification) and turns each change into a NewCapture.
final class PasteboardMonitor {
    /// Marker we add to our own writes so they are never re-captured.
    static let internalType = NSPasteboard.PasteboardType("local.mypaste.internal")

    /// nspasteboard.org conventions plus a few vendor-specific markers for secrets.
    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
        "Pasteboard generator type", "net.antelle.keeweb", internalType.rawValue,
    ]

    private static let maxTextBytes = 2_000_000
    private static let maxImageBytes = 30_000_000

    private let pasteboard = NSPasteboard.general
    private var lastChangeCount: Int
    private var timer: Timer?
    private let prefs: Preferences
    var onCapture: ((NewCapture) -> Void)?

    init(prefs: Preferences) {
        self.prefs = prefs
        lastChangeCount = pasteboard.changeCount
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.35, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(timer!, forMode: .common)
    }

    /// Call right after writing to the pasteboard ourselves.
    func skipCurrent() { lastChangeCount = pasteboard.changeCount }

    private func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        guard !prefs.capturePaused, let capture = capture() else { return }
        onCapture?(capture)
    }

    private func capture() -> NewCapture? {
        let types = pasteboard.types ?? []
        guard !types.isEmpty, !types.contains(where: { Self.skipTypes.contains($0.rawValue) }) else { return nil }
        let app = NSWorkspace.shared.frontmostApplication
        if let id = app?.bundleIdentifier, prefs.excludedBundleIDs.contains(id) { return nil }

        let fileURLs = (pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL]) ?? []
        var text = pasteboard.string(forType: .string)
        if let t = text, t.utf8.count > Self.maxTextBytes { text = String(t.prefix(Self.maxTextBytes / 4)) }
        let rtf = types.contains(.rtf) ? pasteboard.data(forType: .rtf) : nil
        let html = types.contains(.html) ? pasteboard.data(forType: .html) : nil

        var png: Data?
        var size = CGSize.zero
        if fileURLs.isEmpty, types.contains(.png) || types.contains(.tiff),
           let raw = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff),
           raw.count <= Self.maxImageBytes, let rep = NSBitmapImageRep(data: raw) {
            png = types.contains(.png) ? raw : rep.representation(using: .png, properties: [:])
            size = CGSize(width: rep.pixelsWide, height: rep.pixelsHigh)
        }

        let facts = CaptureFacts(string: text, hasRTF: rtf != nil, hasHTML: html != nil, hasImage: png != nil,
                                 fileURLs: fileURLs, hasURLType: types.contains(.URL))
        var kind = Classifier.kind(for: facts)
        if kind == .text, (text ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return nil }

        let keepsRich = kind == .richText || kind == .code
        let hashSource: Data
        switch kind {
        case .file: hashSource = Data(fileURLs.map(\.path).joined(separator: "\n").utf8)
        case .image: hashSource = png ?? Data()
        default: hashSource = Data((text ?? "").utf8)
        }
        let hash = kind.rawValue + ":" + SHA256.hash(data: hashSource).map { String(format: "%02x", $0) }.joined()

        let textual: Set<ContentKind> = [.text, .richText, .code, .link, .email, .phone]
        let reason = textual.contains(kind) ? text.flatMap(SensitiveDetector.reason(for:)) : nil
        let sensitive = reason?.rawValue
        // An Aadhaar looks like a phone number and a UPI ID like an email; file them as text.
        if reason?.isIdentifier == true { kind = .text }

        return NewCapture(kind: kind,
                          text: kind == .image ? nil : (kind == .file ? fileURLs.map(\.lastPathComponent).joined(separator: "\n") : text),
                          rtf: keepsRich ? rtf : nil, html: keepsRich && rtf == nil ? html : nil,
                          imagePNG: kind == .image ? png : nil,
                          imageWidth: Int(size.width), imageHeight: Int(size.height),
                          filePaths: fileURLs.map(\.path),
                          sourceBundleID: app?.bundleIdentifier, sourceAppName: app?.localizedName,
                          contentHash: hash, sensitiveReason: sensitive)
    }
}
